1	//! Manual atomic TEST_ONLY adapter. No DrmSurface or output manager is created:
2	//! their active teardown/legacy test paths can change real display state.
3	use crate::{
4	    output::{Assignment, Format, Plan},
5	    target::{self, Backend, TestFailure, TestReport, TestStage},
6	};
7	use smithay::{
8	    backend::{
9	        allocator::{
10	            Allocator, Buffer, Fourcc, Modifier,
11	            dmabuf::{AsDmabuf, Dmabuf},
12	            gbm::{GbmAllocator, GbmBuffer, GbmBufferFlags, GbmDevice},
13	        },
14	        drm::{DrmDevice, DrmDeviceFd},
15	        renderer::{Bind, Frame, Renderer, gles::GlesRenderer},
16	    },
17	    reexports::drm::control::{
18	        self, AtomicCommitFlags, Device as _, FbCmd2Flags, ResourceHandle, atomic::AtomicModeReq,
19	    },
20	    utils::{Rectangle, Transform},
21	};
22	use std::{cell::Cell, collections::BTreeMap, rc::Rc};
23	fn fail(stage: TestStage) -> TestFailure {
24	    TestFailure::at(stage)
25	}
26	fn io(stage: TestStage, error: std::io::Error) -> TestFailure {
27	    TestFailure {
28	        stage,
29	        errno: error.raw_os_error(),
30	    }
31	}
32	#[derive(Clone, Copy)]
33	enum Object {
34	    Framebuffer(control::framebuffer::Handle),
35	    Blob(u64),
36	}
37	struct Lease {
38	    fd: DrmDeviceFd,
39	    object: Object,
40	    failures: Rc<Cell<u64>>,
41	}
42	impl Drop for Lease {
43	    fn drop(&mut self) {
44	        let result = match self.object {
45	            Object::Framebuffer(fb) => self.fd.destroy_framebuffer(fb),
46	            Object::Blob(blob) => self.fd.destroy_property_blob(blob),
47	        };
48	        if result.is_err() {
49	            self.failures.set(self.failures.get().saturating_add(1));
50	        }
51	    }
52	}
53	struct Properties {
54	    object: control::RawResourceHandle,
55	    values: BTreeMap<String, (control::property::Handle, u64)>,
56	}
57	impl Properties {
58	    fn read<H: ResourceHandle>(drm: &DrmDevice, handle: H) -> Result<Self, TestFailure> {
59	        let values = drm
60	            .get_properties(handle)
61	            .map_err(|e| io(TestStage::Properties, e))?;
62	        if values.as_props_and_values().0.len() > 256 {
63	            return Err(fail(TestStage::Properties));
64	        }
65	        let mut map = BTreeMap::new();
66	        for (id, value) in values {
67	            let info = drm
68	                .get_property(id)
69	                .map_err(|e| io(TestStage::Properties, e))?;
70	            let name = info
71	                .name()
72	                .to_str()
73	                .map_err(|_| fail(TestStage::Properties))?
74	                .to_owned();
75	            if map.insert(name, (id, value)).is_some() {
76	                return Err(fail(TestStage::Properties));
77	            }
78	        }
79	        Ok(Self {
80	            object: handle.into(),
81	            values: map,
82	        })
